// ---------------------------------------------------------------------------
// ASYNC

export const runTasks = async <T=hash,>(
		lTasks: ListrTask<T>[],
		ctx: T,
		hOptions: hash = {}
		): AutoPromise<T> => {

	const listr = new Listr<T>(lTasks, {
		concurrent: false,
		exitOnError: false,
		forceUnicode: true,
		ctx,
		renderer: 'default',
		rendererOptions: {
			clearOutput: true,
			logger: listrLogger,
			icon: {
				PENDING: '⏳',
				COMPLETED: () => '✅',
				FAILED: '❌',
				RETRY: '🔄',
				SKIPPED_WITH_COLLAPSE: '⏩',
				SKIPPED_WITHOUT_COLLAPSE: '⏩',
				ROLLING_BACK: '↩️',
				ROLLED_BACK: '↩️',
				WAITING: '⏳'
				},
			color: {
				FAILED: (msg?: string) => colorize(msg || '', 'red'),
				COMPLETED: (msg?: string) => colorize(msg || '', 'green'),
				ROLLED_BACK: (msg?: string) => colorize(msg || '', 'magenta')
				}
			},
		...hOptions
		})
	await listr.run()
	return await ctx
}

